<script setup lang="ts">
/**
 * Atlasflow logo lockup → mark (launch video end card, AE "combined logo").
 *
 * Paths are Atlasflow's own logo (flow-ui d-atlasflow-logo.vue). Pure function
 * of layer time (useStageTime):
 *   0–1 s     mark + "Atlasflow" wordmark side by side
 *   1–1.5 s   the wordmark slides left behind a moving edge into the mark;
 *             the mark moves to the center and grows to 150 %
 * Fade / scale / blur-in and the final lift are layer keyframes in the comp.
 * Layout is in comp px of a 1080p frame (the stage is 960 × 300, centered).
 */
const t = useStageTime();

function bezier(x1: number, y1: number, x2: number, y2: number) {
  const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;
  const cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
  return (x: number) => {
    if (x <= 0) return 0;
    if (x >= 1) return 1;
    let lo = 0, hi = 1, s = x;
    for (let i = 0; i < 24; i++) {
      s = (lo + hi) / 2;
      if (((ax * s + bx) * s + cx) * s < x) lo = s;
      else hi = s;
    }
    return ((ay * s + by) * s + cy) * s;
  };
}
/** AE: out 14 % with speed (y1 ≈ 1), in 66 %. */
const ease = bezier(0.14, 1, 0.34, 1);
const k = computed(() => ease((t.value - 1) / 0.5));

const W = 960, H = 300;
// Mark: center x −235 → 0 (relative to the frame center), 110 → 165 px.
const markSize = computed(() => 110 + 55 * k.value);
const markX = computed(() => -235 * (1 - k.value));
// Wordmark: left edge at −134, slides 225 px left; the reveal edge sweeps 245 px right.
const WORD_W = 412;
const wordX = computed(() => -134 - 225 * k.value);
const edge = computed(() => -144 + 245 * k.value);
</script>

