      :style="{
        left: `${W / 2 + wordX}px`,
        width: `${WORD_W}px`,
        transform: 'translateY(-50%)',
        clipPath: `inset(-20px -20px -20px ${Math.max(0, edge - wordX)}px)`,
      }"
